/* =========================================================================
   Meridian — shared maths / expression engine
   -------------------------------------------------------------------------
   Classic script. Attaches to window.CalcEngine. No imports, no exports,
   no eval, no new Function, no DOM, no timers, no randomness. Loads from
   file:// with a plain <script src="static/js/engine.js"> tag.

   What lives here
     1. tokenize(source)            -> { ok, tokens } | { ok:false, message, position }
     2. parse(source)               -> { ok, ast, source } | error
     3. evaluate(source, options)   -> { ok, value, formatted } | error
     4. compile(source, options)    -> { ok, fn, source, variable } | error
        fn(x) is a reusable sampler; domain problems yield NaN (never throws)
     5. format  — shared number formatting for every mode
     6. constants / FUNCTIONS / angle helpers

   Grammar (recursive descent, no eval)
     expression    := additive
     additive      := multiplicative (('+' | '-') multiplicative)*
     multiplicative:= unary (('*' | '/' | '%' | implicit) unary)*
     unary         := ('-' | '+') unary | power
     power         := postfix ('^' unary)?            right associative
     postfix       := primary ('!' | degree | '%')*   ('!' factorial, '°' degrees)
     primary       := number | constant | variable | call | '(' expression ')'
     call          := name '(' (expression (',' expression)*)? ')'

   Implicit multiplication (multiplier directly before a value)
     2x   3(4+5)   (1+2)(3+4)   2sin(x)   pi x   4!x
   It binds at the multiplicative level, i.e. left to right, so 1/2x is
   (1/2)·x — the behaviour of a handheld calculator keypad.

   Angles
     options.angleMode: 'rad' (default) | 'deg' | 'grad'
     Also accepted: options.degrees === true, options.angle === 'deg'.
     Trig functions convert input per mode; inverse trig converts output.
     A literal degree sign ('°' or 'deg' postfix) always means ×π/180, so
     sin(48°) equals 0.7431 in both rad and deg mode.

   Never throws to the caller. Every failure is a structured value:
     { ok: false, message: 'Unexpected ")"', position: 7, near: ')…' }
   where position is 1-based (0 when unknown) and near is a short excerpt.
   ========================================================================= */

(function (global) {
  'use strict';

  var VERSION = '1.0.0';
  var DEFAULT_SIG = 12; // preview UI advertises 12 significant digits
  var DEFAULT_ANGLE_MODE = 'rad';

  /* -----------------------------------------------------------------------
     small utilities
     ----------------------------------------------------------------------- */

  function isFiniteNumber(v) {
    return typeof v === 'number' && isFinite(v);
  }

  function clampInt(value, min, max, fallback) {
    var n = Number(value);
    if (!isFinite(n)) return fallback;
    n = Math.round(n);
    if (n < min) return min;
    if (n > max) return max;
    return n;
  }

  function makeError(message, position, near) {
    var err = { ok: false, message: String(message), position: position || 0 };
    if (near) err.near = near;
    return err;
  }

  function excerpt(source, index) {
    if (typeof source !== 'string' || index == null) return '';
    var from = Math.max(0, index - 6);
    var to = Math.min(source.length, index + 7);
    var head = from > 0 ? '\u2026' : '';
    var tail = to < source.length ? '\u2026' : '';
    return head + source.slice(from, to).replace(/\s+/g, ' ') + tail;
  }

  /* -----------------------------------------------------------------------
     angle helpers
     ----------------------------------------------------------------------- */

  function normalizeAngleMode(mode) {
    if (mode == null) return null;
    var m = String(mode).toLowerCase().replace(/[^a-z]/g, '');
    if (!m) return null;
    if (m === 'deg' || m === 'degree' || m === 'degrees' || m === 'd') return 'deg';
    if (m === 'rad' || m === 'radian' || m === 'radians' || m === 'r') return 'rad';
    if (m === 'grad' || m === 'gradian' || m === 'gradians' || m === 'gon' || m === 'g') {
      return 'grad';
    }
    return null;
  }

  function resolveAngleMode(options) {
    if (typeof options === 'string') return normalizeAngleMode(options) || DEFAULT_ANGLE_MODE;
    if (!options || typeof options !== 'object') return DEFAULT_ANGLE_MODE;
    var explicit =
      options.angleMode != null
        ? options.angleMode
        : options.angle != null
        ? options.angle
        : options.angleUnit != null
        ? options.angleUnit
        : options.units != null
        ? options.units
        : null;
    var mode = normalizeAngleMode(explicit);
    if (mode) return mode;
    if (options.degrees === true) return 'deg';
    if (options.radians === true) return 'rad';
    return DEFAULT_ANGLE_MODE;
  }

  function toRadians(value, angleMode) {
    if (angleMode === 'deg') return (value * Math.PI) / 180;
    if (angleMode === 'grad') return (value * Math.PI) / 200;
    return value;
  }

  function fromRadians(value, angleMode) {
    if (angleMode === 'deg') return (value * 180) / Math.PI;
    if (angleMode === 'grad') return (value * 200) / Math.PI;
    return value;
  }

  /* -----------------------------------------------------------------------
     constants and functions
     ----------------------------------------------------------------------- */

  var CONSTANTS = {
    pi: Math.PI,
    '\u03c0': Math.PI,
    e: Math.E,
    tau: Math.PI * 2,
    '\u03c4': Math.PI * 2,
    phi: (1 + Math.sqrt(5)) / 2,
    '\u03c6': (1 + Math.sqrt(5)) / 2
  };

  // name aliases resolved before lookup (unicode input from a keypad)
  var NAME_ALIASES = {
    '\u03c0': 'pi',
    '\u03c4': 'tau',
    '\u03c6': 'phi',
    '**': '^'
  };

  function tanImpl(args, ctx) {
    var r = toRadians(args[0], ctx.angleMode);
    var c = Math.cos(r);
    if (Math.abs(c) < 1e-15) return Math.sin(r) >= 0 ? Infinity : -Infinity;
    return Math.tan(r);
  }

  function checkDomain(ok, message) {
    return ok ? null : message;
  }

  /* Each function: { min, max, impl(args, ctx) } — impl may return
     { error: 'message' } style by throwing a tagged object that the
     evaluator turns into ctx.error. */
  var FUNCTIONS = {
    sin: { min: 1, max: 1, impl: function (a, c) { return Math.sin(toRadians(a[0], c.angleMode)); } },
    cos: { min: 1, max: 1, impl: function (a, c) { return Math.cos(toRadians(a[0], c.angleMode)); } },
    tan: { min: 1, max: 1, impl: tanImpl },
    asin: {
      min: 1, max: 1,
      impl: function (a, c) {
        if (a[0] < -1 || a[0] > 1) throw domainError('asin needs a value between \u22121 and 1');
        return fromRadians(Math.asin(a[0]), c.angleMode);
      }
    },
    acos: {
      min: 1, max: 1,
      impl: function (a, c) {
        if (a[0] < -1 || a[0] > 1) throw domainError('acos needs a value between \u22121 and 1');
        return fromRadians(Math.acos(a[0]), c.angleMode);
      }
    },
    atan: { min: 1, max: 1, impl: function (a, c) { return fromRadians(Math.atan(a[0]), c.angleMode); } },
    atan2: {
      min: 2, max: 2,
      impl: function (a, c) { return fromRadians(Math.atan2(a[0], a[1]), c.angleMode); }
    },
    sinh: { min: 1, max: 1, impl: function (a) { return Math.sinh(a[0]); } },
    cosh: { min: 1, max: 1, impl: function (a) { return Math.cosh(a[0]); } },
    tanh: { min: 1, max: 1, impl: function (a) { return Math.tanh(a[0]); } },
    ln: {
      min: 1, max: 1,
      impl: function (a) {
        if (a[0] < 0) throw domainError('ln is undefined for negative numbers');
        return Math.log(a[0]);
      }
    },
    log: { min: 1, max: 1, impl: function (a) { return logBase(a[0], 10); } },
    log10: { min: 1, max: 1, impl: function (a) { return logBase(a[0], 10); } },
    log2: { min: 1, max: 1, impl: function (a) { return logBase(a[0], 2); } },
    exp: { min: 1, max: 1, impl: function (a) { return Math.exp(a[0]); } },
    sqrt: {
      min: 1, max: 1,
