    fn.lastError = null;
    fn.source = prepared.parsed.source;
    fn.expression = prepared.parsed.source;
    fn.variable = variableName;
    fn.variables = variables;
    fn.angleMode = prepared.angleMode;
    fn.ast = prepared.parsed.ast;

    return {
      ok: true,
      fn: fn,
      sample: fn,
      source: prepared.parsed.source,
      variable: variableName,
      variables: variables,
      angleMode: prepared.angleMode,
